function guessDayFirst(values) {
  let dm = false, md = false, ampm = false, dot = 0, slash = 0;
  for (const v of values) {
    const m = String(v || '').trim().match(/^(\d{1,2})([\/.-])(\d{1,2})\2\d{2,4}(.*)$/); if (!m) continue;
    if (+m[1] > 12) dm = true; else if (+m[3] > 12) md = true;
    if (/\b[ap]m\b/i.test(m[4])) ampm = true;
    if (m[2] === '.') dot++; else slash++;
  }
  if (dm !== md) return dm;      // eindeutiger Beleg: ein Teil > 12
  if (dm && md) return null;     // widersprüchlich: nicht raten
  if (ampm) return false;        // 12-Stunden-Uhr = US-Format
  if (dot || slash) return dot >= slash;
  return null;
}
